import React, { useState, useRef } from "react";

const imagePaths = [
  "/images/a1.gif",
  "/images/a2.gif",
  "/images/a2.png",
];

const TILE_SIZE = 270;
const GRID = 4;

function ImageCompositor() {
  const [selectedImages, setSelectedImages] = useState([]);
  const canvasRef = useRef(null);

  const toggleSelect = (img) => {
    setSelectedImages((prev) =>
      prev.includes(img) ? prev.filter((i) => i !== img) : [...prev, img]
    );
  };

  const loadImage = (src) => {
    return new Promise((resolve) => {
      const img = new Image();
      img.crossOrigin = "anonymous";
      img.onload = () => resolve(img);
      img.src = src;
    });
  };

  const getShuffledIndices = () => {
    const indices = Array.from({ length: GRID * GRID }, (_, i) => i);
    for (let i = indices.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [indices[i], indices[j]] = [indices[j], indices[i]];
    }
    return indices;
  };

  const thresholdImage = (image) => {
    const tempCanvas = document.createElement("canvas");
    tempCanvas.width = 1080;
    tempCanvas.height = 1080;
    const tempCtx = tempCanvas.getContext("2d");
    tempCtx.drawImage(image, 0, 0, 1080, 1080);
    const imageData = tempCtx.getImageData(0, 0, 1080, 1080);
    const data = imageData.data;

    for (let i = 0; i < data.length; i += 4) {
      const avg = (data[i] + data[i + 1] + data[i + 2]) / 3;
      const value = avg > 128 ? 255 : 0;
      data[i] = data[i + 1] = data[i + 2] = value;
    }

    tempCtx.putImageData(imageData, 0, 0);
    const result = new Image();
    result.src = tempCanvas.toDataURL();
    return result;
  };

  const generateImage = async () => {
    const canvas = canvasRef.current;
    const ctx = canvas.getContext("2d");
    ctx.clearRect(0, 0, 1080, 1080);

    const loadedImages = await Promise.all(
      selectedImages.map((src) => loadImage(src))
    );

    for (let i = 0; i < loadedImages.length; i++) {
      const image = loadedImages[i];
      const shuffledIndices = getShuffledIndices();

      const tempCanvas = document.createElement("canvas");
      tempCanvas.width = 1080;
      tempCanvas.height = 1080;
      const tempCtx = tempCanvas.getContext("2d");
      tempCtx.drawImage(image, 0, 0, 1080, 1080);

      const tiles = [];
      for (let y = 0; y < GRID; y++) {
        for (let x = 0; x < GRID; x++) {
          const tile = tempCtx.getImageData(
            x * TILE_SIZE,
            y * TILE_SIZE,
            TILE_SIZE,
            TILE_SIZE
          );
          tiles.push(tile);
        }
      }

      const newCanvas = document.createElement("canvas");
      newCanvas.width = 1080;
      newCanvas.height = 1080;
      const newCtx = newCanvas.getContext("2d");
      shuffledIndices.forEach((toIndex, fromIndex) => {
        const toX = (toIndex % GRID) * TILE_SIZE;
        const toY = Math.floor(toIndex / GRID) * TILE_SIZE;
        newCtx.putImageData(tiles[fromIndex], toX, toY);
      });

      const finalImage = new Image();
      finalImage.src = newCanvas.toDataURL();
      await new Promise((res) => (finalImage.onload = res));

      if (i % 2 === 0) {
        const bw = thresholdImage(finalImage);
        await new Promise((res) => (bw.onload = res));

        const maskCanvas = document.createElement("canvas");
        maskCanvas.width = 1080;
        maskCanvas.height = 1080;
        const maskCtx = maskCanvas.getContext("2d");
        maskCtx.drawImage(bw, 0, 0, 1080, 1080);
        const maskData = maskCtx.getImageData(0, 0, 1080, 1080);

        const baseData = ctx.getImageData(0, 0, 1080, 1080);
        for (let j = 0; j < baseData.data.length; j += 4) {
          const alpha = maskData.data[j] / 255;
          baseData.data[j + 3] *= alpha;
        }
        ctx.putImageData(baseData, 0, 0);
      } else {
        ctx.drawImage(finalImage, 0, 0, 1080, 1080);
      }
    }
  };

  return (
    <div>
      <div style={{ display: "flex", justifyContent: "center", flexWrap: "wrap" }}>
        {imagePaths.map((img, index) => (
          <img
            key={index}
            src={img}
            alt={`img-${index}`}
            style={{
              width: 120,
              height: 120,
              margin: 10,
              cursor: "pointer",
              border: selectedImages.includes(img) ? "3px solid #FFD666" : "1px solid #999",
            }}
            onClick={() => toggleSelect(img)}
          />
        ))}
      </div>
      <button onClick={generateImage}>Generate</button>
      <br />
      <canvas ref={canvasRef} width={1080} height={1080} style={{ marginTop: 20, border: "1px solid #555" }} />
    </div>
  );
}

export default ImageCompositor;
